  const sackTotal=(currentProfile.storage?.sacks||[]).reduce((sum,x)=>sum+x.count,0);
  $('#moduleTitle').textContent='IronPath · Dwarven Forge';
  const slots=data.processes?.length?data.processes.map(x=>`<div class="forge-process"><span>${escapeHtml(x.name)}</span><small data-finish="${x.finishesAt||0}">${x.finishesAt?durationText((x.finishesAt-Date.now())/1000):'Time unavailable'}</small></div>`).join(''):'<p class="ironpath-note">No active forge processes were exposed by this profile.</p>';
  const goals=ironpathGoals.filter(goal=>ironpathCategory==='all'||recipeFor(goal.recipeId)?.category===ironpathCategory).map(goal=>{const recipe=recipeFor(goal.recipeId);if(!recipe)return'';const plan=ironpathPlan(recipe.id,goal.quantity),fallback=recipe.category==='drills'?'https://raw.githubusercontent.com/InventivetalentDev/minecraft-assets/1.21.4/assets/minecraft/textures/item/diamond_pickaxe.png':'';return`<article class="ironpath-goal ${recipe.category==='drills'||plan.materials.length>6?'ironpath-goal-wide':''}"><header><img class="ironpath-item-icon" src="${recipe.icon||icon(recipe.id)}" alt="" data-fallback="${fallback}" onerror="if(this.dataset.fallback){this.src=this.dataset.fallback;this.dataset.fallback=''}else if(!this.dataset.retried){this.dataset.retried='1';this.src=this.src.split('?')[0]+'?retry=1'}else this.hidden=true"><div class="ironpath-goal-title"><span class="ironpath-category-label">${escapeHtml(ironpathCategories[recipe.category]||recipe.category)}</span><h3>${goal.quantity>1?`${goal.quantity}x `:''}${escapeHtml(recipe.name)}</h3><small>HOTM ${recipe.hotm} / ${durationText(plan.time)}</small></div><button class="ironpath-remove" data-ironpath-remove="${goal.id}" aria-label="Remove ${escapeHtml(recipe.name)}">x</button></header><div class="ironpath-progress"><span style="width:${plan.percent}%"></span></div><div class="ironpath-progress-copy"><span>${plan.percent}% ready</span><span>${plan.materials.filter(x=>x.missing).length} raw materials missing</span></div><div class="ironpath-list-label">Recipe</div><div class="forge-tree">${renderForgeTree(plan.tree,icon)}</div></article>`}).join('');
