function searchableItems(){const found=[];const add=(item,location)=>{if(item)found.push({...item,location})};const storage=currentStorage||{};(storage.inventory||[]).forEach(x=>add(x,'Inventory'));(storage.enderChest||[]).forEach(x=>add(x,'Ender Chest'));(storage.personalVault||[]).forEach(x=>add(x,'Personal Vault'));(storage.backpacks||[]).forEach(pack=>(pack.items||[]).forEach(x=>add(x,pack.name)));(storage.bags||[]).filter(bag=>bag.id!=='talisman_bag').forEach(bag=>(bag.items||[]).forEach(x=>add(x,bag.name)));(currentProfile?.equipment||[]).forEach(x=>add(x,x.group||'Equipment'));(currentProfile?.accessories?.items||[]).forEach(x=>add(x,'Accessory Bag'));(currentLoadouts?.armorSets||[]).forEach(set=>(set.items||[]).forEach(x=>add(x,`Wardrobe Set ${set.id}`)));(currentLoadouts?.equipmentSets||[]).forEach(set=>(set.items||[]).forEach(x=>add(x,`Equipment Set ${set.id}`)));return found}
function renderItemSearch(query){const term=query.trim().toLowerCase(),matches=searchableItems().filter(item=>`${item.name} ${item.id} ${item.location}`.toLowerCase().includes(term)).slice(0,200);$('#wardrobeContent').innerHTML=term?`<div class="item-search-results"><div class="item-search-summary">${matches.length}${matches.length===200?'+':''} matching item${matches.length===1?'':'s'}</div>${matches.length?`<div class="item-search-grid">${matches.map(item=>`<article class="item-search-result"><div class="item-search-icon">${storageSlot(item)}</div><div><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.location)} · ${number.format(item.count||1)}</small></div></article>`).join('')}</div>`:'<div class="empty-equipment">No matching items found across this profile.</div>'}</div>`:'<div class="empty-equipment">Type an item name, ID, or storage location to search this profile.</div>'}
function renderStorage(tab){if(tab==='sacks'){const sacks=currentStorage.sacks||[];$('#wardrobeContent').innerHTML=sacks.length?`<div class="sack-grid">${sacks.map(x=>`<div class="sack-item"><span>${escapeHtml(x.name)}</span><strong>${number.format(x.count)}</strong></div>`).join('')}</div>`:'<div class="empty-equipment">No sack counts exposed. Make sure inventory API access is enabled.</div>';return}let groups=[];if(tab==='inventory'){const items=currentStorage.inventory||[];groups=[{name:'Main Inventory',items:[...items.slice(9),...items.slice(0,9)]}]}if(tab==='enderChest')groups=[{name:'Ender Chest',items:currentStorage.enderChest},{name:'Personal Vault',items:currentStorage.personalVault}];if(tab==='backpacks')groups=currentStorage.backpacks;if(tab==='bags')groups=(currentStorage.bags||[]).filter(x=>x.id!=='talisman_bag');const layout=tab==='backpacks'?'storage-groups backpack-grid':'storage-groups';$('#wardrobeContent').innerHTML=groups.length?`<div class="${layout}">${groups.map(x=>storageGroup(x.name,x.items)).join('')}</div>`:'<div class="empty-equipment">No storage data exposed by this profile.</div>'}
function renderWardrobe(tab='armorSets'){
  const content=$('#wardrobeContent');
  if(['inventory','enderChest','backpacks','bags','sacks'].includes(tab)){renderStorage(tab);return}
  if(tab==='loadouts'){
    content.innerHTML=currentLoadouts.loadouts.length?`<div class="set-grid">${currentLoadouts.loadouts.map(loadout=>{const armor=currentLoadouts.armorSets.find(x=>x.id===loadout.armorSetId),equipment=currentLoadouts.equipmentSets.find(x=>x.id===loadout.equipmentSetId),items=[...(armor?.items||[]),...(equipment?.items||[])];return `<article class="set-card loadout-card"><div class="loadout-number">${loadout.id}</div><div><strong>${escapeHtml(loadout.name)}</strong><small>Armor ${loadout.armorSetId||'—'} · Equipment ${loadout.equipmentSetId||'—'}</small><div class="set-items" style="margin-top:10px">${items.map(modalItem).join('')}</div></div></article>`}).join('')}</div>`:'<div class="empty-equipment">No saved loadouts exposed by this profile.</div>';
    return;
  }
  const label=tab==='armorSets'?'Wardrobe':'Equipment';
  const sets=currentLoadouts[tab]||[];
  content.innerHTML=sets.length?`<div class="set-grid">${sets.map(set=>`<article class="set-card ${set.equipped?'active':''}"><div class="set-head"><span>${label.toUpperCase()} SLOT ${set.id}</span>${set.equipped?'<b>● EQUIPPED</b>':''}</div><div class="set-items">${set.items.map(modalItem).join('')}</div></article>`).join('')}</div>`:'<div class="empty-equipment">No saved sets exposed by this profile.</div>';
}
function openWardrobe(tab,updateRoute=true){if(typeof tab==='string'){document.querySelectorAll('#wardrobeTabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab))}const active=$('#wardrobeTabs .active').dataset.tab;renderWardrobe(active);$('#wardrobeModal').classList.add('open');$('#wardrobeModal').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';if(updateRoute)setRoute(active)}
function closeWardrobe(updateRoute=true){$('#wardrobeModal').classList.remove('open');$('#wardrobeModal').setAttribute('aria-hidden','true');document.body.style.overflow='';if(updateRoute)setRoute(null)}
function renderSkills(values = {}) {
  const skills=[['⚔','Combat','combat'],['☘','Farming','farming'],['⛏','Mining','mining'],['✦','Enchanting','enchanting'],['♜','Taming','taming']];
  $('#skillsList').innerHTML=skills.map(([i,n,key])=>{const level=values[key] ?? 0; return `<div class="skill"><span class="skill-icon">${i}</span><div><b>${n}</b><small>${Math.round(level * 10) / 10}</small></div><strong>${Math.floor(level)}</strong></div>`}).join('');
}

const number = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });
function compact(value) { return new Intl.NumberFormat('en-US', { notation:'compact', maximumFractionDigits:1 }).format(value || 0); }
function relativeTime(timestamp){const seconds=Math.max(0,Math.floor((Date.now()-timestamp)/1000));if(seconds<60)return 'now';if(seconds<3600)return `${Math.floor(seconds/60)}m`;if(seconds<86400)return `${Math.floor(seconds/3600)}h`;if(seconds<2592000)return `${Math.floor(seconds/86400)}d`;return new Date(timestamp).toLocaleDateString()}
function renderActivity(events=[]){const icons={dungeon:'♜',shard:'◆',objective:'✓'};$('#activityList').innerHTML=events.length?events.map(event=>`<div class="activity-item"><span class="activity-icon">${icons[event.type]||'✦'}</span><div><b>${escapeHtml(event.title)}</b><small>${escapeHtml(event.detail)}</small></div><time title="${new Date(event.timestamp).toLocaleString()}">${relativeTime(event.timestamp)}</time></div>`).join(''):'<div class="activity-item"><span class="activity-icon">—</span><div><b>No recent public activity</b><small>This profile may have limited API data</small></div></div>'}
function statCard(title,big,rows=[],featured=false){return `<article class="module-card ${featured?'featured':''}"><small>${escapeHtml(title).toUpperCase()}</small><strong class="big">${big}</strong>${rows.length?`<dl>${rows.map(([k,v])=>`<div><dt>${escapeHtml(String(k))}</dt><dd>${escapeHtml(String(v))}</dd></div>`).join('')}</dl>`:''}</article>`}
function renderModule(type){if(!currentProfile)return;const p=currentProfile,n=x=>number.format(x||0),c=x=>compact(x||0);let title='',html='';if(type==='slayer'){title='Slayer';html=`<div class="module-grid">${p.slayers.map(x=>statCard(x.name,`LVL ${x.level}`,[['XP',n(x.xp)],...x.kills.map((v,i)=>[`Tier ${i+1} kills`,n(v)])],x.xp>0)).join('')}</div>`}if(type==='dungeons'){const d=p.dungeonDetails;title='Dungeons';html=`<div class="module-grid">${statCard('Catacombs',n(d.level),[['XP',n(d.experience)],['Secrets',n(d.secrets)],['Selected class',d.selectedClass||'—']],true)}${d.classes.map(x=>statCard(x.name,n(x.level),[['XP',n(x.experience)]])).join('')}</div><h3>Floor records</h3><table class="module-table"><thead><tr><th>Floor</th><th>Completions</th><th>Fastest</th></tr></thead><tbody>${d.floors.map(x=>`<tr><td>Floor ${x.floor}</td><td>${n(x.completions)}</td><td>${x.fastest?(x.fastest/1000).toFixed(1)+'s':'—'}</td></tr>`).join('')}</tbody></table>`}if(type==='pets'){title=`Pets · ${p.pets.length}`;html=`<div class="module-grid">${p.pets.map(x=>statCard(x.name,x.tier,[['XP',n(x.experience)],['Held item',x.heldItem||'None'],['Candy',x.candyUsed],['Status',x.active?'ACTIVE':'Stored']],x.active)).join('')}</div>`}if(type==='mining'){const m=p.mining;title='Mining';html=`<div class="module-grid">${['mithril','gemstone','glacite'].map(k=>statCard(`${k} powder`,c(m[k].available),[['Spent',c(m[k].spent)],['Total',c(m[k].available+m[k].spent)]],k==='mithril')).join('')}</div><h3>Crystals</h3><div class="module-grid">${m.crystals.map(x=>statCard(x.name,x.state,[['Found',x.totalFound]])).join('')}</div>`}if(type==='garden'){const g=p.garden;title='Garden';html=`<div class="module-grid">${statCard('Garden XP',n(g.experience),[['Copper',n(g.copper)],['Plots',g.plots]],true)}${statCard('Visitors',n(g.visitorsCompleted),[['Unique visitors',g.uniqueVisitors]])}${g.composter?statCard('Composter',n(g.composter.compost),[['Organic matter',n(g.composter.organicMatter)],['Fuel',n(g.composter.fuel)] ]):''}</div><h3>Crop collection</h3><table class="module-table"><tbody>${g.crops.map(x=>`<tr><td>${escapeHtml(x.name)}</td><td>Upgrade ${x.upgrade}</td><td>${n(x.amount)}</td></tr>`).join('')}</tbody></table>`}if(type==='bestiary'){const b=p.bestiary;title='Bestiary';html=`<div class="module-grid">${statCard('Total kills',n(b.totalKills),[['Unique variants',b.unique],['Last killed',b.lastKilled]],true)}</div><h3>Top mobs</h3><table class="module-table"><tbody>${b.mobs.map((x,i)=>`<tr><td>#${i+1}</td><td>${escapeHtml(x.name)}</td><td>${n(x.kills)}</td></tr>`).join('')}</tbody></table>`}if(type==='networth'){const w=p.networth;title='Net Worth Estimate';html=`<div class="module-grid">${statCard('Estimated total',c(w.total),[['Exact total',n(w.total)]],true)}${statCard('Purse',c(w.purse))}${statCard('Bank',c(w.bank))}${statCard('Inventory',c(w.inventory))}${statCard('Storage',c(w.storage))}${statCard('Wardrobe',c(w.wardrobe))}</div><p class="module-note">${escapeHtml(w.note)}</p>`}$('#moduleTitle').textContent=title;$('#moduleContent').innerHTML=html}
function renderNotebook(){if(!currentPlayer)return;$('#moduleTitle').textContent='Notebook';notebookNotes=readLocalList(personalStorageKey('notebook'));if(!notebookNotes.some(x=>x.id===activeNoteId))activeNoteId=notebookNotes[0]?.id||null;renderNotebookEditor()}
function renderNotebookEditor(){const active=notebookNotes.find(x=>x.id===activeNoteId);$('#moduleContent').innerHTML=`<div class="notebook"><aside><button id="newNote">+ NEW NOTE</button><div>${notebookNotes.map(x=>`<button class="note-link ${x.id===activeNoteId?'active':''}" data-note-id="${x.id}"><strong>${escapeHtml(x.title||'Untitled')}</strong><small>${new Date(x.updated||Date.now()).toLocaleDateString()}</small></button>`).join('')}</div></aside><section class="note-editor">${active?`<div class="note-tools"><span id="noteStatus">Saved</span><button id="deleteNote">Delete</button></div><input id="noteTitle" maxlength="80" value="${escapeHtml(active.title)}" placeholder="Note title"><textarea id="noteBody" maxlength="20000" placeholder="Write farming angles, speeds, reminders, or anything important…">${escapeHtml(active.body)}</textarea>`:'<div class="notebook-empty"><b>No notes yet</b><span>Create a note for farming angles, speeds, or anything important.</span></div>'}</section></div>`}
function saveNotebook(){clearTimeout(notebookTimer);const status=$('#noteStatus');if(status)status.textContent='Saving…';notebookTimer=setTimeout(()=>{const saved=writeLocalList(personalStorageKey('notebook'),notebookNotes),next=$('#noteStatus');if(next)next.textContent=saved?'Saved in this browser':'Browser storage is full'},350)}
function durationText(seconds){seconds=Math.max(0,Math.ceil(Number(seconds)||0));if(!seconds)return 'Ready';const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.ceil(seconds%3600/60);return[days&&`${days}d`,hours&&`${hours}h`,minutes&&`${minutes}m`].filter(Boolean).join(' ')}
function ironpathPlan(recipeId,quantity){const data=currentProfile.ironpath||{},recipes=data.recipes||[],byId=Object.fromEntries(recipes.map(x=>[x.id,x])),pool={...(data.counts||{})},missing={},total={},time={value:0};const raw=(id,amount)=>{const recipe=byId[id];if(!recipe){total[id]=(total[id]||0)+amount;return}for(const item of recipe.ingredients)raw(item.id,item.count*amount)};const use=(id,amount)=>{const owned=Math.min(Number(pool[id]||0),amount);pool[id]=Number(pool[id]||0)-owned;const left=amount-owned;if(!left)return;const recipe=byId[id];if(!recipe){missing[id]=(missing[id]||0)+left;return}time.value+=recipe.duration*left;for(const item of recipe.ingredients)use(item.id,item.count*left)};raw(recipeId,quantity);use(recipeId,quantity);const materials=Object.entries(total).map(([id,needed])=>({id,name:recipes.flatMap(x=>x.ingredients).find(x=>x.id===id)?.name||id,needed,missing:Number(missing[id]||0)})).sort((a,b)=>b.missing-a.missing);const all=materials.reduce((s,x)=>s+x.needed,0),have=materials.reduce((s,x)=>s+(x.needed-x.missing),0);return{materials,time:time.value,percent:all?Math.round(have/all*100):100}}
function ironpathStorageKey(player=currentPlayer,profile=currentProfile?.id){return `skyfolio-ironpath-${String(player||'').toLowerCase()}-${String(profile||'default')}`}
function saveIronpath(){if(!currentPlayer||!currentProfile)return;writeLocalList(ironpathStorageKey(),ironpathGoals)}
function drawIronpath(){const data=currentProfile?.ironpath||{recipes:[],processes:[],counts:{}},recipes=data.recipes||[],sackTotal=(currentProfile.storage?.sacks||[]).reduce((sum,x)=>sum+x.count,0);$('#moduleTitle').textContent='IronPath · Dwarven Forge';const slots=data.processes?.length?data.processes.map(x=>`<div class="forge-process"><span>${escapeHtml(x.name)}</span><small data-finish="${x.finishesAt||0}">${x.finishesAt?durationText((x.finishesAt-Date.now())/1000):'Time unavailable'}</small></div>`).join(''):'<p class="ironpath-note">No active forge processes were exposed by this profile.</p>';const goals=ironpathGoals.map(goal=>{const recipe=recipes.find(x=>x.id===goal.recipeId);if(!recipe)return'';const plan=ironpathPlan(goal.recipeId,goal.quantity);return`<article class="ironpath-goal"><header><div><h3>${goal.quantity>1?`${goal.quantity}× `:''}${escapeHtml(recipe.name)}</h3><small>HOTM ${recipe.hotm} · ${durationText(plan.time)} base forge work remaining</small></div><button class="ironpath-remove" data-ironpath-remove="${goal.id}">Remove</button></header><div class="ironpath-progress"><span style="width:${plan.percent}%"></span></div><div class="material-list">${plan.materials.map(item=>`<div class="material-row ${item.missing?'':'ready'}"><b>${escapeHtml(item.name)}</b><span>${number.format(item.needed-item.missing)} / ${number.format(item.needed)}</span><small>${item.missing?`${number.format(item.missing)} missing`:'READY'}</small></div>`).join('')}</div></article>`}).join('');$('#moduleContent').innerHTML=`<div class="ironpath"><section class="ironpath-hero"><div class="ironpath-summary"><div class="eyebrow">IRONMAN PROGRESSION</div><h3>Your forge route, from what you actually own</h3><p>IronPath combines inventory, Ender Chest, backpacks, bags, wardrobe and sacks. Intermediate forge items are consumed before their ingredients are expanded.</p><div class="ironpath-kpis"><div><strong>${data.hotm||0}</strong><small>HOTM</small></div><div><strong>${number.format(Object.keys(data.counts||{}).length)}</strong><small>Tracked items</small></div><div><strong>${compact(sackTotal)}</strong><small>In sacks</small></div></div></div><div class="forge-slots"><div class="eyebrow">ACTIVE FORGE</div><h3>${data.processes?.length||0} slot${data.processes?.length===1?'':'s'} running</h3>${slots}</div></section><form class="ironpath-add" id="ironpathAdd"><select id="ironpathRecipe">${recipes.map(x=>`<option value="${x.id}">${escapeHtml(x.name)} · HOTM ${x.hotm}</option>`).join('')}</select><input id="ironpathQuantity" type="number" min="1" max="64" value="1" aria-label="Quantity"><button>Add goal</button></form><div class="ironpath-goals">${goals||'<div class="notebook-empty"><b>No forge goals yet</b><span>Choose an item above to calculate its complete material route.</span></div>'}</div><p class="ironpath-note">Times use base forge durations; Quick Forge and mayor perks can shorten them. ${data.sacksAvailable?'Sack counts are included.':'Sack data is unavailable because inventory API access is disabled or not exposed.'}</p></div>`;clearInterval(ironpathTimer);ironpathTimer=setInterval(()=>document.querySelectorAll('[data-finish]').forEach(el=>el.textContent=durationText((Number(el.dataset.finish)-Date.now())/1000)),1000)}
function renderIronpath(){if(!currentPlayer||!currentProfile)return;const key=ironpathStorageKey();$('#moduleTitle').textContent='IronPath';if(ironpathKey!==key){ironpathGoals=readLocalList(key);ironpathKey=key}drawIronpath()}
