function renderEvents(){const dayMs=20*60*1000,yearDays=372,epoch=1560275700000,now=Date.now(),elapsed=Math.max(0,now-epoch),day=Math.floor(elapsed/dayMs)%yearDays,year=Math.floor(elapsed/(dayMs*yearDays))+1,dayTime=elapsed%dayMs,dayNumber=day+1,hour=Math.floor(dayTime/dayMs*24),minute=Math.floor((dayTime/dayMs*24-hour)*60),events=[{name:'Spooky Festival',day:81,icon:'☾',detail:'Earn candy and hunt special mobs.'},{name:'Jerry Workshop',day:25,icon:'❄',detail:'Seasonal winter island is open.'},{name:'New Year Celebration',day:1,icon:'✦',detail:'Celebrate the start of a new SkyBlock year.'},{name:'Fishing Festival',day:2,icon:'♒',detail:'Rare sea creatures appear while fishing.'}],upcoming=events.map(x=>({...x,days:(x.day-dayNumber+yearDays)%yearDays})).sort((a,b)=>a.days-b.days),next=upcoming[0],nextIn=next.days*dayMs+((24-hour)*60-minute)*60*1000;$('#moduleTitle').textContent='Event Timeline';$('#moduleContent').innerHTML=`<div class="calendar-hero"><div><small>SKYBLOCK CALENDAR</small><strong>Year ${year} · Day ${dayNumber}</strong><span>${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')} in-game</span></div><div><small>NEXT EVENT</small><strong>${escapeHtml(next.name)}</strong><span>Starts in ${durationText(nextIn/1000)}</span></div></div><div class="event-timeline">${upcoming.map((x,i)=>{const remaining=x.days*dayMs+((24-hour)*60-minute)*60*1000,realH=Math.floor(remaining/3600000),realM=Math.floor(remaining%3600000/60000);return `<article class="event-card ${i===0?'next':''}"><span class="event-icon">${x.icon}</span><div><small>${x.days===0?'ACTIVE':'IN '+x.days+' SKYBLOCK DAY'+(x.days===1?'':'S')}<br>${realH}h ${String(realM).padStart(2,'0')}m</small><h3>${escapeHtml(x.name)}</h3><p>${escapeHtml(x.detail)}</p></div></article>`}).join('')}</div><p class="module-note event-note">Calendar dates are calculated from the standard SkyBlock 20-minute day cycle.</p>`}
function electionEnd(current){const raw=current?.end||current?.end_ts||current?.endTime||current?.election_end||current?.electionEnd;if(raw===undefined||raw===null)return 0;const value=Number(raw);return value<1e12?value*1000:value}
function mayorCountdown(end){if(!end)return 'Unavailable';const remaining=end-Date.now();if(remaining<=0)return 'Election ended';const total=Math.floor(remaining/1000),days=Math.floor(total/86400),hours=Math.floor(total%86400/3600),minutes=Math.floor(total%3600/60),seconds=total%60;return `${days?`${days}d `:''}${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`}
function renderSpecialModule(type){const p=currentProfile,n=x=>number.format(x||0);if(type==='accessories'){const a=p.accessories;$('#moduleTitle').textContent='Accessory Bag';$('#moduleContent').innerHTML=`<div class="module-grid">${statCard('Magical Power',n(a.magicalPower),[['Selected power',a.selectedPower],['Unique accessories',a.unique],['Bag upgrades',a.upgrades]],true)}${statCard('Unlocked Powers',a.unlockedPowers.length,a.unlockedPowers.map(x=>[x,'✓']))}${statCard('Tuning',a.tuning.length,a.tuning.map(x=>[x.name,`+${x.value}`]))}${statCard('Duplicates',a.duplicates.length,a.duplicates.map(x=>[x.name,`×${x.count}`]))}</div><h3>Accessory Bag · ${a.items.length} occupied slots</h3><div class="inventory-slots">${a.items.map(storageSlot).join('')}</div>`}if(type==='mayor'){clearInterval(mayorTimer);const e=p.mayor||{},m=e.mayor||{},current=e.current||{},candidates=[...(current.candidates||[])].sort((a,b)=>Number(b.votes||0)-Number(a.votes||0)),total=candidates.reduce((s,x)=>s+Number(x.votes||0),0),end=electionEnd(current);$('#moduleTitle').textContent='Mayor & Election';$('#moduleContent').innerHTML=`<div class="mayor-hero"><div class="mayor-current"><small>CURRENT MAYOR</small><strong>${escapeHtml(m.name||'Unknown')}</strong><span>${m.perks?.length||0} active perk${m.perks?.length===1?'':'s'}</span></div><div class="mayor-countdown"><small>NEXT ELECTION ENDS IN</small><strong id="mayorCountdown">${mayorCountdown(end)}</strong><span>Election Year ${current.year||'—'}</span></div></div><div class="mayor-columns"><article class="module-card mayor-perks"><small>MAYOR PERKS</small>${(m.perks||[]).map(x=>`<div class="mayor-perk"><b>${escapeHtml(x.name)}</b><p class="module-note">${minecraftFormat(x.description)}</p></div>`).join('')||'<p class="module-note">No active perks reported.</p>'}</article>${m.minister?`<article class="module-card mayor-minister"><small>MINISTER</small><strong class="big">${escapeHtml(m.minister.name)}</strong><b>${escapeHtml(m.minister.perk?.name||'')}</b><p class="module-note">${minecraftFormat(m.minister.perk?.description||'')}</p></article>`:''}</div><div class="mayor-election-heading"><div><small>LIVE ELECTION</small><h3>Election Year ${current.year||'—'}</h3></div><span>${candidates.length} candidate${candidates.length===1?'':'s'}</span></div><div class="mayor-candidates">${candidates.map((x,i)=>{const percent=total?Math.round(Number(x.votes||0)/total*100):0;return `<article class="mayor-candidate"><div class="mayor-candidate-top"><span class="mayor-rank">${i+1}</span><strong>${escapeHtml(x.name||'Unknown')}</strong><b>${percent}%</b></div><div class="mayor-vote-bar"><i style="width:${percent}%"></i></div><small>${n(x.votes)} votes · ${x.perks?.length||0} perks</small></article>`}).join('')||'<p class="module-note">No candidates reported.</p>'}</div><p class="module-note mayor-updated">Election data updated ${e.lastUpdated?new Date(e.lastUpdated).toLocaleString():'—'}.</p>`;if(end)mayorTimer=setInterval(()=>{const el=$('#mayorCountdown');if(el)el.textContent=mayorCountdown(end)},1000)}}
function openModule(type,updateRoute=true){closeWardrobe(false);if(type==='notebook')renderNotebook();else if(type==='ironpath')renderIronpath();else if(type==='events')renderEvents();else if(['accessories','mayor'].includes(type))renderSpecialModule(type);else renderModule(type);$('#moduleModal').classList.add('open');$('#moduleModal').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';document.querySelectorAll('#moduleNav button').forEach(x=>x.classList.toggle('active',x.dataset.module===type));if(updateRoute)history.pushState({module:type},'',profileUrl(modulePaths[type]))}
function closeModule(updateRoute=true){$('#moduleModal').classList.remove('open');$('#moduleModal').setAttribute('aria-hidden','true');document.body.style.overflow='';document.querySelectorAll('#moduleNav button').forEach(x=>x.classList.remove('active'));if(updateRoute)history.pushState({},'',profileUrl())}
function applyProfile(data) {
  const p=data.profile; currentPlayer=p.username;currentProfile=p;
  document.title=`Skyfolio | ${p.username}`;
  profileMeta=data.meta||null;updateFreshness();clearInterval(freshnessTimer);freshnessTimer=setInterval(updateFreshness,1000);
  syncGoals(p.username);
  $('#playerName').textContent=p.username;
  renderAvatar(p.username);
  $('#profileMeta').innerHTML=`<span class="status-dot"></span> Live API data <i></i> ${escapeHtml(p.cuteName)} profile`;
  $('#skyblockLevel').textContent=number.format(p.skyblockLevel);
  $('#levelInteger').textContent=Math.floor(p.skyblockLevel);
  const progress=Math.max(0,Math.min(99,(p.skyblockLevel%1)*100));
  $('#levelProgress').style.width=`${progress}%`;
  $('#levelRing').style.background=`radial-gradient(circle,#151a1b 58%,transparent 60%),conic-gradient(var(--lime) ${progress}%,#293027 0)`;
  $('#levelXp').textContent=`${Math.round(progress)} / 100 to next level`;
  $('#skillAverage').textContent=number.format(p.skillAverage);
  $('#catacombs').textContent=number.format(p.catacombs);
  $('#slayerXp').textContent=compact(p.slayerXp);
  $('#profileCount').textContent=p.profileCount;
  $('#purse').textContent=number.format(p.purse);
  $('#bank').textContent=number.format(p.bank);
  renderSkills(p.skills);
  renderEquipment(p.equipment);
  currentLoadouts=p.loadouts||{armorSets:[],equipmentSets:[],loadouts:[]};
  currentStorage=p.storage||{inventory:[],enderChest:[],personalVault:[],backpacks:[],bags:[],sacks:[]};
  const storedItems=[...currentStorage.inventory,...currentStorage.enderChest,...currentStorage.personalVault,...currentStorage.backpacks.flatMap(x=>x.items),...currentStorage.bags.flatMap(x=>x.items)].filter(Boolean).length;
  $('#storageSummary').textContent=`${storedItems} occupied slots · ${currentStorage.backpacks.length} backpacks · ${currentStorage.sacks?.length||0} sack resources`;
  const widgetSettings=JSON.parse(localStorage.getItem('skyfolio-widgets')||'{}');const widgetMap={overview:'.overview',purse:'.purse',activity:'.activity',equipment:'#equipmentCard',storage:'#storageCard',planner:'.planner',skills:'.skills',collection:'.collection'};Object.entries(widgetMap).forEach(([id,selector])=>{const element=$(selector);if(element)element.classList.toggle('widget-hidden',widgetSettings[id]===false)});updateDashboardColumns();
  const route=readRoute();if(route.tab)openWardrobe(route.tab,false);
  if(route.module)openModule(route.module,false);
  const collections=p.collections||{percent:0,maxed:0,total:0,tiersCompleted:0,totalTiers:0};
  $('#collectionPercent').textContent=`${collections.percent}%`;
  $('#collectionBar').style.width=`${collections.percent}%`;
  $('#collectionSummary').textContent=`${collections.maxed} of ${collections.total} collections maxed · ${collections.tiersCompleted} / ${collections.totalTiers} tiers`;
  renderActivity(p.activity);
  const select=$('#profileSelect');
  select.innerHTML=data.profiles.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${escapeHtml(x.cuteName)}${x.selected?' · active':''}</option>`).join('');
  select.disabled=false;
  initViewer(p.username);
  document.querySelector('.brand').href=profileUrl();
}

let lastLoad={name:'',profileId:'',force:false},loadSequence=0;
function setProfileState(mode,title,copy=''){const state=$('#profileState'),retry=$('#profileRetry');document.body.classList.toggle('profile-loading',mode==='loading');document.body.classList.toggle('profile-loaded',mode==='success');state.classList.toggle('error',mode==='error');state.hidden=mode==='success';retry.hidden=mode!=='error';$('#profileStateTitle').textContent=title;$('#profileStateCopy').textContent=copy}
async function loadProfile(name, profileId='', force=false) {
  const input=$('#playerInput'),sequence=++loadSequence; input.disabled=true;lastLoad={name,profileId,force};
  setProfileState('loading',`Loading ${name}`,force?'Refreshing live Hypixel data…':'Fetching profile, inventories, collections, and equipment…');
  showToast(`Loading ${name} from Hypixel…`);
  try {
    const params=new URLSearchParams();if(profileId)params.set('profile',profileId);if(force)params.set('refresh','1');const query=params.size?`?${params}`:'';
    const response=await fetch(`/api/profile/${encodeURIComponent(name)}${query}`);
    const data=await response.json();
    if(!response.ok) throw new Error(data.error || 'Could not load this profile.');
    if(sequence!==loadSequence)return;normalizeRoute(data.profile.username);applyProfile(data);setProfileState('success','Profile loaded');showToast(`Loaded ${data.profile.username} · ${data.profile.cuteName}`);
  } catch(error) {if(sequence===loadSequence){setProfileState('error',`Couldn’t load ${name}`,error.message);showToast(error.message)}}
  finally {if(sequence===loadSequence){input.disabled=false;$('#refreshBtn').classList.remove('loading')}}
}
function updateFreshness(){if(!profileMeta)return;const age=Math.max(0,Date.now()-profileMeta.fetchedAt),left=Math.max(0,profileMeta.expiresAt-Date.now()),el=$('#freshness'),updated=age<60000?'Updated now':`Updated ${relativeTime(profileMeta.fetchedAt)} ago`;el.textContent=`${updated} · cache ${Math.ceil(left/1000)}s`;el.classList.toggle('fresh',age<60000)}

