let petFilter='',petRarity='all',petSort='level';
function filteredPets(){const groups=new Map();for(const pet of currentProfile?.pets||[]){const key=`${pet.type}:${pet.tier}:${pet.heldItemId||''}`,existing=groups.get(key);if(!existing||pet.experience>existing.experience)groups.set(key,{...pet,count:(existing?.count||0)+1,active:pet.active||existing?.active})}return[...groups.values()].filter(x=>(petRarity==='all'||x.tier===petRarity)&&`${x.name} ${x.tier} ${x.heldItem||''}`.toLowerCase().includes(petFilter.toLowerCase())).sort((a,b)=>petSort==='name'?a.name.localeCompare(b.name):petSort==='rarity'?b.rarity-a.rarity||b.level-a.level:Number(b.active)-Number(a.active)||b.level-a.level||b.experience-a.experience)}
function drawPets(){const root=$('#petResults');if(!root)return;const pets=filteredPets();$('#petResultCount').textContent=`${pets.length} shown`;root.innerHTML=pets.length?pets.map(x=>`<article class="pet-card ${x.active?'active':''}"><div class="pet-texture"><img loading="lazy" decoding="async" src="${x.icon}" alt="${escapeHtml(x.name)}" onerror="this.hidden=true">${x.count>1?`<b class="pet-count">×${x.count}</b>`:''}</div><div class="pet-info"><div class="pet-heading"><div><small>${escapeHtml(x.tier)} · LEVEL ${x.level}/${x.max}</small><h3>${escapeHtml(x.name)}</h3></div>${x.active?'<span>ACTIVE</span>':''}</div><div class="pet-level-bar"><i style="width:${x.progress}%"></i></div><div class="pet-progress-copy"><span>${x.progress}% to next level</span><span>${number.format(x.experience)} XP</span></div><dl><div><dt>Held item</dt><dd>${x.heldItemId?`<img src="/api/item-texture/${encodeURIComponent(x.heldItemId)}?v=4" alt="">`:''}${escapeHtml(x.heldItem||'None')}</dd></div><div><dt>Candy used</dt><dd>${x.candyUsed}</dd></div><div><dt>Soulbound</dt><dd>${x.soulbound?'Yes':'No'}</dd></div></dl></div></article>`).join(''):'<div class="notebook-empty"><b>No matching pets</b><span>Try another search or rarity.</span></div>'}
function renderPetsPerfect(){const pets=currentProfile?.pets||[],unique=new Set(pets.map(x=>x.type)).size;$('#moduleTitle').textContent=`Pets · ${pets.length}`;$('#moduleContent').innerHTML=`<div class="pet-summary"><div><small>PET SCORE</small><strong>${number.format(currentProfile?.petScore||0)}</strong></div><div><small>UNIQUE PETS</small><strong>${unique}</strong></div><div><small>ACTIVE PET</small><strong>${escapeHtml(pets.find(x=>x.active)?.name||'None')}</strong></div></div><div class="pet-tools"><label class="item-search"><span>⌕</span><input id="petSearch" type="search" placeholder="Search pets or held items…"></label><select id="petRarity"><option value="all">All rarities</option>${['COMMON','UNCOMMON','RARE','EPIC','LEGENDARY','MYTHIC'].map(x=>`<option>${x}</option>`).join('')}</select><select id="petSort"><option value="level">Active & level</option><option value="rarity">Rarity</option><option value="name">Name</option></select><small id="petResultCount"></small></div><div class="pet-grid" id="petResults"></div>`;petFilter='';petRarity='all';petSort='level';drawPets()}
function renderEssence(){const data=currentProfile?.essence||{balances:[],perks:[]},shops=data.balances.map(balance=>({...balance,perks:data.perks.filter(perk=>perk.shop===balance.id)}));$('#moduleTitle').textContent='Essence Shops';$('#moduleContent').innerHTML=`<div class="essence-shops">${shops.map(shop=>`<article class="essence-shop essence-${shop.id.toLowerCase()}"><header><div class="essence-icon">✧</div><div><small>${escapeHtml(shop.name).toUpperCase()} ESSENCE SHOP</small><strong>${number.format(shop.amount)} essence</strong></div></header><div class="essence-shop-upgrades">${shop.perks.map(perk=>`<div><span>${escapeHtml(perk.name)}</span><b>Level ${perk.level}</b></div>`).join('')||'<small class="essence-shop-empty">No upgrades purchased in this shop.</small>'}</div></article>`).join('')||'<p class="module-note">No essence balances were exposed for this profile.</p>'}</div>`}
function renderMuseum(){const data=currentProfile?.museum||{items:[],special:[],total:0,value:0},items=[...data.items,...data.special],categories=['Armor','Weapons','Equipment','Special','Other'];$('#moduleTitle').textContent='Museum';$('#moduleContent').innerHTML=`<div class="museum-summary"><div><small>DONATED ITEMS</small><strong>${number.format(data.total)}</strong></div><div><small>MUSEUM VALUE</small><strong>${compact(data.value)}</strong></div><div><small>SPECIAL ITEMS</small><strong>${data.special.length}</strong></div></div><div class="museum-categories">${categories.map(category=>{const group=items.filter(x=>(x.category||'Other')===category);if(!group.length)return'';return`<section class="museum-category"><header><div><small>MUSEUM CATEGORY</small><h3>${category}</h3></div><span>${group.length} item${group.length===1?'':'s'}</span></header><div class="museum-grid">${group.map(x=>`<article class="museum-item"><img loading="lazy" decoding="async" src="${x.icon}" alt="${escapeHtml(x.name)}" onerror="this.hidden=true"><div><strong>${escapeHtml(x.name)}</strong><small>${x.donatedAt?`Donated ${new Date(x.donatedAt).toLocaleDateString()}`:'Donated'}${x.borrowing?' · Borrowed':''}</small></div></article>`).join('')}</div></section>`}).join('')||'<div class="notebook-empty"><b>No public museum donations found</b><span>Museum API access may be disabled for this profile.</span></div>'}</div>`}
function renderMinions(){const data=currentProfile?.minions||{uniqueCrafts:0,types:0,minions:[]};$('#moduleTitle').textContent='Minions';$('#moduleContent').innerHTML=`<div class="section-kpis"><div><small>UNIQUE CRAFTS</small><strong>${data.uniqueCrafts}</strong></div><div><small>MINION TYPES</small><strong>${data.types}</strong></div><div><small>HIGHEST TIER</small><strong>${Math.max(0,...data.minions.map(x=>x.tier))}</strong></div></div><label class="item-search section-search"><span>⌕</span><input id="minionSearch" type="search" placeholder="Search minions…"></label><div class="minion-grid" id="minionResults">${data.minions.map(x=>`<article class="minion-card" data-minion-name="${escapeHtml(x.name.toLowerCase())}"><img src="${x.icon}" alt="${escapeHtml(x.name)}" onerror="this.hidden=true"><div><strong>${escapeHtml(x.name)}</strong><small>Highest crafted tier ${x.tier}</small><div class="tier-dots">${Array.from({length:12},(_,i)=>`<i class="${x.tiers.includes(i+1)?'done':''}"></i>`).join('')}</div></div></article>`).join('')}</div>`}
function renderCollections(){const data=currentProfile?.collections||{categories:[],percent:0};$('#moduleTitle').textContent='Collections';$('#moduleContent').innerHTML=`<div class="section-kpis"><div><small>OVERALL</small><strong>${data.percent}%</strong></div><div><small>MAXED</small><strong>${data.maxed}/${data.total}</strong></div><div><small>TIERS</small><strong>${data.tiersCompleted}/${data.totalTiers}</strong></div></div><div class="collection-categories">${data.categories.map(category=>`<section class="collection-category"><header><h3>${escapeHtml(category.name)}</h3><span>${category.items.filter(x=>x.percent===100).length}/${category.items.length} maxed</span></header><div>${category.items.map(x=>`<article><div><strong>${escapeHtml(x.name)}</strong><small>${number.format(x.amount)} · Tier ${x.completed}/${x.totalTiers}</small></div><div class="collection-item-bar"><i style="width:${x.percent}%"></i></div><b>${x.percent}%</b></article>`).join('')}</div></section>`).join('')}</div>`}
function renderCrimson(){const data=currentProfile?.crimson||{kuudra:[],dojo:[]};$('#moduleTitle').textContent='Crimson Isle';$('#moduleContent').innerHTML=`<div class="section-kpis"><div><small>SELECTED FACTION</small><strong>${escapeHtml(data.faction)}</strong></div><div><small>MAGE REPUTATION</small><strong>${number.format(data.mages)}</strong></div><div><small>BARBARIAN REPUTATION</small><strong>${number.format(data.barbarians)}</strong></div></div><div class="world-columns"><section><div class="section-heading"><small>KUUDRA</small><h3>Completions</h3></div>${data.kuudra.map(x=>`<div class="world-stat"><span>${escapeHtml(x.name)}</span><b>${number.format(x.kills)}</b></div>`).join('')||'<p class="module-note">No Kuudra completions reported.</p>'}</section><section><div class="section-heading"><small>DOJO</small><h3>Challenge Scores</h3></div>${data.dojo.map(x=>`<div class="world-stat"><span>${escapeHtml(x.name)}</span><b>${number.format(x.points)}</b></div>`).join('')||'<p class="module-note">No Dojo scores reported.</p>'}</section></div>`}
function renderRift(){const data=currentProfile?.rift||{timecharms:[]};$('#moduleTitle').textContent='The Rift';$('#moduleContent').innerHTML=`<div class="section-kpis"><div><small>VISITS</small><strong>${number.format(data.visits)}</strong></div><div><small>MOTES</small><strong>${number.format(data.motes)}</strong></div><div><small>ENIGMA SOULS</small><strong>${number.format(data.enigmaSouls)}</strong></div><div><small>MCGRUBBER BURGERS</small><strong>${number.format(data.burgers)}</strong></div></div><div class="section-heading"><small>RIFT PROGRESSION</small><h3>Timecharms</h3></div><div class="timecharm-grid">${data.timecharms.map(x=>`<article class="${x.unlocked?'unlocked':''}"><span>◈</span><div><strong>${escapeHtml(x.name)}</strong><small>${x.unlockedAt?new Date(x.unlockedAt).toLocaleDateString():x.unlocked?'Obtained':'Not obtained'}</small></div></article>`).join('')||'<p class="module-note">No Timecharm data was exposed.</p>'}</div>`}
function renderMisc(){const groups=currentProfile?.misc||[];$('#moduleTitle').textContent='Miscellaneous Stats';$('#moduleContent').innerHTML=`<div class="misc-groups">${groups.map(group=>`<section><header><h3>${escapeHtml(group.name)}</h3><span>${group.items.length} stats</span></header>${group.items.map(x=>`<div class="world-stat"><span>${escapeHtml(x.name)}</span><b>${number.format(x.value)}</b></div>`).join('')}</section>`).join('')||'<p class="module-note">No miscellaneous statistics were exposed.</p>'}</div>`}
const renderModuleComplete=renderModule;
renderModule=function(type){if(type==='pets')return renderPetsPerfect();if(type==='essence')return renderEssence();if(type==='museum')return renderMuseum();if(type==='minions')return renderMinions();if(type==='collections')return renderCollections();if(type==='crimson')return renderCrimson();if(type==='rift')return renderRift();if(type==='misc')return renderMisc();return renderModuleComplete(type)};
$('#moduleContent').addEventListener('input',e=>{if(e.target.id==='petSearch'){petFilter=e.target.value;drawPets()}});
$('#moduleContent').addEventListener('change',e=>{if(e.target.id==='petRarity'){petRarity=e.target.value;drawPets()}if(e.target.id==='petSort'){petSort=e.target.value;drawPets()}});
$('#moduleContent').addEventListener('input',e=>{if(e.target.id==='minionSearch')document.querySelectorAll('[data-minion-name]').forEach(card=>card.hidden=!card.dataset.minionName.includes(e.target.value.toLowerCase()))});
const sharedPlayer=readRoute().player;
if(sharedPlayer){$('#playerInput').value=sharedPlayer;loadProfile(sharedPlayer)}
